/** confusable character map: source code point → replacement string */
export const confusableMap: Map<number, string> = /* #__PURE__ */ (() => {
	const d = k.split(',');
	const s = v.split('|');
	const m = new Map<number, string>();
	let p = 0;
	for (let i = 0; i < d.length; i++) {
		p += parseInt(d[i], 36);
		m.set(p, s[i]);
	}
	return m;
})();
